// Compute clinic-local date/time context so the agent never has to guess 'today'.
const tz = 'Asia/Karachi';
const now = new Date(new Date().toLocaleString('en-US', { timeZone: tz }));
const dayNames = ['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'];
const pad = (n) => String(n).padStart(2, '0');
const fmtDate = (d) => `${d.getFullYear()}-${pad(d.getMonth()+1)}-${pad(d.getDate())}`;

const days = [];
for (let i = 0; i <= 3; i++) {
  const d = new Date(now);
  d.setDate(now.getDate() + i);
  days.push({ date: fmtDate(d), day_name: dayNames[d.getDay()], is_sunday: d.getDay() === 0 });
}

const currentTime = `${pad(now.getHours())}:${pad(now.getMinutes())}`;
const next3 = days.slice(1).map(d => `${d.day_name} ${d.date}${d.is_sunday ? ' (CLOSED - Sunday)' : ''}`).join(', ');

const date_context_text = `Today is ${days[0].day_name}, ${days[0].date}. Current clinic time is ${currentTime} (PKT, Asia/Karachi). The next 3 days are: ${next3}. Clinic is closed all day Sunday.`;

const incoming = $input.first().json;
return [{ json: { ...incoming, date_context_text, today_date: days[0].date, today_day_name: days[0].day_name, current_time: currentTime } }];

// Grab all incoming items (e.g., 3 calendar events)
const items = $input.all();

// 1. Process and format every calendar event into a clean array
const busySlotsList = items.map(item => {
  const startIso = item.json.start?.dateTime || item.json.start;
  const endIso = item.json.end?.dateTime || item.json.end;

  if (!startIso || !endIso) {
    return {
      "Date": "N/A",
      "Time Slot": "N/A"
    };
  }

  // Extract Date (YYYY-MM-DD)
  const formattedDate = startIso.split('T')[0];

  // Extract HH:MM directly from ISO string without timezone shifts
  const extractTimeStr = (isoString) => {
    const timePart = isoString.split('T')[1];
    if (!timePart) return "00:00";
    const [hours, minutes] = timePart.split(':');
    return `${hours}:${minutes}`;
  };

  const startTimeStr = extractTimeStr(startIso);
  const endTimeStr = extractTimeStr(endIso);

  return {
    "Date": formattedDate,
    "Time Slot": `${startTimeStr} to ${endTimeStr}`
  };
}).filter(slot => slot.Date !== "N/A"); // Remove empty/invalid slots

// 2. Extract base user message details from the first item
const firstItemJson = items[0]?.json || {};

// 3. Return as 1 SINGLE ITEM to prevent AI Agent duplicate executions
return [{
  json: {
    ...firstItemJson,
    busy_slots_list: busySlotsList
  }
}];

return $input.all().map(item => {
  // 1. Grab raw output string from AI Agent
  let rawOutput = item.json.output?.text || item.json.output || item.json.text || item.json.reply || item.json;

  if (typeof rawOutput === 'object' && rawOutput !== null) {
    if (rawOutput.reply) return { json: { isAction: false, action: rawOutput.action || "normal_chat", reply: rawOutput.reply, data: rawOutput.data || {} } };
    rawOutput = JSON.stringify(rawOutput);
  }

  let cleanText = String(rawOutput || "").trim();

  // Helper function to force clean line breaks
  const formatText = (str) => {
    if (typeof str !== 'string') return str;
    return str
      .replace(/\\\\n/g, '\n')
      .replace(/\\n/g, '\n')
      .replace(/\\"/g, '"')
      .replace(/\\\\/g, '\\')
      .split(/\r?\n/)
      .join(String.fromCharCode(10));
  };

  const tryParseJSON = (str) => {
    try { return JSON.parse(str); } catch (e) { return null; }
  };

  // Strip Markdown code blocks if present
  if (cleanText.includes("```")) {
    cleanText = cleanText.replace(/```(?:json)?/gi, "").replace(/```/g, "").trim();
  }

  // Attempt JSON parsing
  let parsedObj = tryParseJSON(cleanText);
  if (!parsedObj) {
    const jsonMatch = cleanText.match(/\{[\s\S]*\}/);
    if (jsonMatch) parsedObj = tryParseJSON(jsonMatch[0]);
  }

  // 2. If valid JSON object with reply
  if (parsedObj && typeof parsedObj === 'object' && parsedObj.reply) {
    const action = String(parsedObj.action || "normal_chat").toLowerCase();
    const isFinalAction = ["book", "reschedule", "cancel"].includes(action);

    return {
      json: {
        isAction: isFinalAction,
        action: action,
        reply: formatText(parsedObj.reply),
        data: parsedObj.data || {}
      }
    };
  }

  // 3. Fallback: If output is empty or plain text, provide a valid structured output
  const fallbackReply = cleanText && cleanText !== "[object Object]" 
    ? formatText(cleanText) 
    : "Thank you for contacting Pak International Hospital. How can I assist you with your appointment today?";

  return {
    json: {
      isAction: false,
      action: "normal_chat",
      reply: fallbackReply,
      data: {}
    }
  };
});

